package fraymus.workspace;
import org.json.*;import org.junit.Test;import static org.junit.Assert.*;import java.util.*;
public class Uncertainty071Test {
 static JSONObject model(double offset,double calibration){var f=new JSONArray();var c=new JSONArray();for(String cell:Uncertainty071.CELLS){for(int i=0;i<6;i++)f.put(new JSONObject().put("cell",cell).put("recordId","fit-"+cell+i).put("residualsM",new JSONArray(new double[]{offset,offset,offset,offset})));for(int i=0;i<9;i++)c.put(new JSONObject().put("cell",cell).put("recordId","cal-"+cell+i).put("residualsM",new JSONArray(new double[]{offset,offset,offset,offset+calibration*i/8})));}return Uncertainty071.fitLabels(f,c);}
 static JSONObject task(){return new JSONObject().put("angleDeg",20).put("frictionRatio",1).put("centerM",.15).put("halfWidthM",.1);}
 static JSONObject decision(){return new JSONObject().put("recover",false).put("speedMps",.2).put("execute",true).put("adaptive",true).put("later",true).put("method","uncertain");}
 @Test public void fittingAndSeparateCalibrationHaveExplicitJointMeaning(){var m=model(.02,.018);for(String key:Uncertainty071.CELLS){var c=m.getJSONObject("cells").getJSONObject(key);assertEquals(9,c.getInt("rank"));assertEquals(9,c.getDouble("multiplier"),1e-12);assertEquals(.02,c.getJSONArray("centerM").getDouble(3),0);assertEquals(.002,c.getJSONArray("scaleM").getDouble(3),0);}var other=model(.02,.036);assertTrue(m.getJSONObject("cells").getJSONObject("slowing-predicted").getJSONArray("centerM").similar(other.getJSONObject("cells").getJSONObject("slowing-predicted").getJSONArray("centerM")));assertEquals(18,other.getJSONObject("cells").getJSONObject("slowing-predicted").getDouble("multiplier"),1e-12);Uncertainty071.verify(m);}
 @Test public void riskySkipGetsEarlyLookAndSafeSkipRemains(){var t=task();var d=decision();assertEquals(-1,ObservationSchedule070.plan(t,d,null).getInt("selectedTick"));var safe=Uncertainty071.schedule(t,d,null,model(0,0));assertEquals(-1,safe.getInt("selectedTick"));assertTrue(safe.getJSONObject("uncertainty071").getBoolean("contained"));var risky=Uncertainty071.schedule(t,d,null,model(.25,.01));assertEquals(92,risky.getInt("selectedTick"));assertTrue(risky.getJSONObject("uncertainty071").getBoolean("forcedLook"));assertEquals(-1,risky.getJSONObject("uncertainty071").getInt("oldSelectedTick"));}
 @Test public void guardNeverPostponesAnAlreadyChosenObservation(){var d=decision();boolean checked=false;for(double w:new double[]{.006,.012,.024}){var t=task().put("halfWidthM",w);var old=ObservationSchedule070.plan(t,d,null);if(old.getInt("selectedTick")>0){var next=Uncertainty071.schedule(t,d,null,model(.5,.01));assertEquals(old.getInt("selectedTick"),next.getInt("selectedTick"));assertFalse(next.getJSONObject("uncertainty071").getBoolean("forcedLook"));checked=true;}}assertTrue(checked);}
 @Test public void modelRecomputesScoresAndRejectsRehashedTampering(){var m=model(0,.01);m.getJSONObject("cells").getJSONObject("slowing-predicted").put("multiplier",.001);m.remove("sha256");m.put("sha256",WorldFrames.hash(m));assertThrows(IllegalStateException.class,()->Uncertainty071.verify(m));assertThrows(IllegalStateException.class,()->Uncertainty071.fitLabels(new JSONArray(),new JSONArray()));}
 @Test public void partitionsAreFreshBalancedAndProspective(){var ids=new HashSet<String>();for(String phase:List.of("fit","calibration","clean","disturbed","unsupported")){var rows=Set.of("fit","calibration").contains(phase)?UncertainStudy071.training(phase):UncertainStudy071.cases(phase);for(Object raw:rows)assertTrue(ids.add(WorldFrames.hash(((JSONObject)raw).getJSONObject("task"))));if(phase.equals("fit")||phase.equals("calibration"))for(String cell:Uncertainty071.CELLS){int n=0;for(Object raw:rows)if(((JSONObject)raw).getString("cell").equals(cell))n++;assertEquals(phase.equals("fit")?6:9,n);}}assertEquals(180,ids.size());for(String phase:List.of("clean","disturbed","unsupported")){for(Object raw:AdaptiveStudy070.cases(phase))assertFalse(ids.contains(WorldFrames.hash(((JSONObject)raw).getJSONObject("task"))));for(Object raw:LaterStudy069.cases(phase))assertFalse(ids.contains(WorldFrames.hash(((JSONObject)raw).getJSONObject("task"))));}for(String phase:List.of("calibration","clean","disturbed","unsupported"))for(Object raw:CalibrationStudy068.cases(phase))assertFalse(ids.contains(WorldFrames.hash(((JSONObject)raw).getJSONObject("task"))));assertEquals(6,UncertainStudy071.parityCases().length());assertEquals(546,UncertainStudy071.manifest().getInt("total"));}
 @Test public void riskySkipLanguageUsesEvidenceReadAndPreservesWebsiteCreation(){for(String s:List.of("Inspect the uncertainty study","Improve uncertainty estimates so it knows when skipping a look is risky","Report calibrated residual coverage")){assertEquals("agent",ChatPolicy044.route(s,new JSONObject(),false));}assertEquals("workbench",ChatPolicy044.route("Build a website about uncertainty estimates",new JSONObject(),false));}
 @Test public void qualificationRequiresCoverageValueAndSensingSavings(){var e=new JSONObject().put("methods",new JSONObject().put("adaptive",new JSONObject().put("successes",35)).put("fixed",new JSONObject().put("extraObservations",144)).put("uncertain",new JSONObject().put("successes",35).put("extraObservations",129))).put("pairedUncertainMinus",new JSONObject().put("adaptive",new JSONObject().put("meanDelta",.005))).put("coverage",new JSONObject().put("jointCoverage",.90));assertTrue(UncertainStudy071.qualifies(e,"clean"));e.getJSONObject("coverage").put("jointCoverage",.84);assertFalse(UncertainStudy071.qualifies(e,"clean"));e.getJSONObject("coverage").put("jointCoverage",.9);e.getJSONObject("methods").getJSONObject("uncertain").put("extraObservations",132);assertFalse(UncertainStudy071.qualifies(e,"clean"));e.getJSONObject("pairedUncertainMinus").getJSONObject("adaptive").put("meanDelta",-.031);assertFalse(UncertainStudy071.qualifies(e,"disturbed"));}
}
